"""Password hashing and session-token generation.

Two kinds of secret are handled here, and they are hashed **differently on
purpose**. Understanding why is the single most important idea in this file.

*Passwords* are chosen by humans, so they are low-entropy and guessable. An
attacker who steals the database will try billions of candidate passwords
against each hash. The defence is to make each guess expensive: Argon2id is
deliberately slow and memory-hungry, so a GPU rig that could try billions of
SHA-256 guesses per second manages only thousands.

*Session tokens* are generated by us from 256 bits of cryptographic
randomness. There is no "guessing" a 256-bit random value -- the search space
is astronomically large. Slow hashing would buy nothing and would add ~50-100ms
to **every authenticated request**. So session tokens get a single fast SHA-256
pass, which is enough to ensure a stolen database dump does not contain usable
session tokens.

Short version: slow hashing defends weak secrets. Random secrets are not weak.
"""

from __future__ import annotations

import hashlib
import secrets

from argon2 import PasswordHasher
from argon2.exceptions import InvalidHashError, VerifyMismatchError

from app.core.logging import get_logger

logger = get_logger(__name__)

# Argon2id with the library's defaults, which track current OWASP guidance.
# Argon2id is the hybrid variant: resistant to both GPU cracking and
# side-channel attacks. Raising these parameters makes hashing slower for us
# *and* for an attacker; the defaults are a sensible balance.
_password_hasher = PasswordHasher()

# Number of random bytes in a session token. 32 bytes = 256 bits.
_SESSION_TOKEN_BYTES = 32

# Passwords longer than this are rejected before hashing. Argon2 has no
# practical length limit, but accepting unbounded input lets an attacker send
# a 100 MB "password" and consume server CPU -- a denial-of-service vector.
MAX_PASSWORD_LENGTH = 1024
MIN_PASSWORD_LENGTH = 12


def hash_password(password: str) -> str:
    """Hash a plaintext password for storage.

    The returned string embeds the algorithm, its parameters, and a randomly
    generated salt, so no salt column is needed. Two identical passwords
    produce different hashes.
    """
    return _password_hasher.hash(password)


def verify_password(password: str, password_hash: str) -> bool:
    """Check a password against a stored hash. Never raises."""
    try:
        _password_hasher.verify(password_hash, password)
    except VerifyMismatchError:
        return False
    except InvalidHashError:
        # A malformed hash in the database is a data-integrity problem, not a
        # valid login. Log it, but never let it authenticate anyone.
        logger.error("Stored password hash is malformed and cannot be verified")
        return False
    except Exception:  # noqa: BLE001 - verification must never crash a login
        logger.exception("Unexpected error while verifying a password")
        return False
    return True


def password_needs_rehash(password_hash: str) -> bool:
    """Whether a stored hash used weaker parameters than we now require.

    Lets us transparently upgrade users to stronger settings the next time
    they log in, since that is the only moment we hold the plaintext.
    """
    try:
        return _password_hasher.check_needs_rehash(password_hash)
    except InvalidHashError:
        return False


def generate_session_token() -> str:
    """Create a new, unguessable session token.

    `secrets` uses the operating system's cryptographic random source. Never
    use `random` for anything security-related -- it is a predictable
    pseudo-random generator, and its output can be reconstructed from a few
    observed values.
    """
    return secrets.token_urlsafe(_SESSION_TOKEN_BYTES)


def hash_session_token(token: str) -> str:
    """Hash a session token for storage.

    SHA-256, deliberately -- see the module docstring. We store only the hash
    so that a leaked database dump contains no usable session tokens, exactly
    as with passwords.
    """
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

